"""Invoice export helper for the billing API, implemented with pydantic 1.10."""
from __future__ import annotations

import json
from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any, List

from pydantic import BaseModel, ValidationError, condecimal, conint, validator


def _format_decimal_2(value: Decimal) -> str:
    """Format a Decimal with exactly two fractional digits."""
    return str(value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def _parse_issued_at(value: Any) -> datetime:
    """Parse an ISO-8601 datetime string or accept a datetime object.
    Naive datetimes are treated as UTC.
    """
    if isinstance(value, datetime):
        dt = value
    elif isinstance(value, str):
        text = value.strip()
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        try:
            dt = datetime.fromisoformat(text)
        except ValueError as exc:
            raise ValueError("invalid issued_at") from exc
    else:
        raise ValueError("invalid issued_at")

    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


class InvoiceLine(BaseModel):
    sku: str
    quantity: conint(ge=1)
    unit_price: condecimal(ge=0)

    @validator("unit_price", pre=True)
    def parse_unit_price(cls, value):
        if isinstance(value, Decimal):
            return value
        if isinstance(value, bool):
            raise ValueError("invalid unit_price")
        try:
            return Decimal(str(value))
        except (InvalidOperation, ValueError, TypeError) as exc:
            raise ValueError("invalid unit_price") from exc


class InvoiceExport(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, value):
        return _parse_issued_at(value)

    def to_export_dict(self) -> dict:
        lines = []
        total = Decimal("0")
        for line in self.lines:
            unit_price = Decimal(line.unit_price)
            lines.append(
                {
                    "sku": line.sku,
                    "quantity": line.quantity,
                    "unit_price": _format_decimal_2(unit_price),
                }
            )
            total += unit_price * Decimal(line.quantity)

        return {
            "number": self.number,
            "issued_at": self.issued_at.strftime("%Y-%m-%dT%H:%M:%SZ"),
            "lines": lines,
            "total": _format_decimal_2(total),
        }


def export_invoice(data: dict) -> str:
    """Validate invoice data with pydantic and return billing-API JSON text.

    Input keys:
      - number: str
      - issued_at: ISO 8601 string or datetime; naive values are treated as UTC
      - lines: list of {sku, quantity>=1, unit_price>=0}

    Output JSON includes:
      - number
      - issued_at formatted as YYYY-MM-DDTHH:MM:SSZ
      - lines with unit_price as a string with exactly two decimals
      - total as a string with exactly two decimals

    Raises ValueError for invalid input.
    """
    try:
        invoice = InvoiceExport.parse_obj(data)
    except ValidationError as exc:
        raise ValueError(str(exc)) from exc
    return json.dumps(invoice.to_export_dict(), separators=(",", ":"))

"""Profile import helper for CSV/JSON rows.

Valid rows are parsed with pydantic and returned as dicts containing:
{"user_id": int, "display_name": str, "bio": str or None, "zip_code": str}

Invalid rows are skipped silently.
"""
from typing import Any, List, Optional

from pydantic import BaseModel, validator


class ImportedProfile(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    @validator("display_name")
    def collapse_display_name_whitespace(cls, value: str) -> str:
        value = " ".join(value.split())
        if not value:
            raise ValueError("display_name must not be blank")
        return value

    @validator("zip_code", pre=True)
    def coerce_zip_code_to_string(cls, value: Any) -> str:
        if isinstance(value, (str, int)):
            return str(value)
        raise TypeError("zip_code must be a string or integer")


def import_profiles(rows: list) -> list:
    """Validate profile rows and return the valid ones as dicts, skipping invalid rows."""
    valid_rows: List[dict] = []
    for row in rows:
        try:
            profile = ImportedProfile.parse_obj(row)
        except Exception:
            continue
        valid_rows.append(
            {
                "user_id": profile.user_id,
                "display_name": profile.display_name,
                "bio": profile.bio,
                "zip_code": profile.zip_code,
            }
        )
    return valid_rows

"""Sign-up payload validation helper built with pydantic 1.10."""

import re
from pydantic import BaseModel, Field, ValidationError, root_validator, validator


class SignUpModel(BaseModel):
    username: str = Field(..., regex=r"^[a-z0-9_]{3,20}$")
    email: str
    phone: str
    password: str = Field(..., min_length=8)
    password_confirm: str

    @validator("email", pre=True)
    def normalize_email(cls, value):
        if not isinstance(value, str):
            raise TypeError("email must be a string")
        value = value.strip().lower()
        if "@" not in value:
            raise ValueError("invalid email")
        return value

    @validator("phone", pre=True)
    def normalize_phone(cls, value):
        if not isinstance(value, str):
            raise TypeError("phone must be a string")
        compact = re.sub(r"[\s.\-()]", "", value)
        if not re.fullmatch(r"\+\d{8,15}", compact):
            raise ValueError("invalid phone number")
        return compact

    @root_validator
    def check_passwords_match(cls, values):
        password = values.get("password")
        confirm = values.get("password_confirm")
        if password is not None and confirm is not None and password != confirm:
            raise ValueError("passwords do not match")
        return values


def validate_signup(data: dict) -> dict:
    """Validate a sign-up payload and return normalized public fields.

    Returns:
        {"username": ..., "email": ..., "phone": <compact phone>}

    Raises:
        ValueError: for any missing or invalid field (pydantic ValidationError is acceptable).
    """
    model = SignUpModel.parse_obj(data)
    return {
        "username": model.username,
        "email": model.email,
        "phone": model.phone,
    }

from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any, Optional

from pydantic import BaseModel, ConfigDict, Field, ValidationError, field_serializer, field_validator, model_validator


_TWO_PLACES = Decimal("0.01")


def _to_decimal_2dp(value: Any) -> Decimal:
    if isinstance(value, bool):
        raise ValueError("unit_price must be a decimal number")
    try:
        dec = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError) as exc:
        raise ValueError("unit_price must be a decimal number") from exc
    if dec < 0:
        raise ValueError("unit_price must be >= 0")
    return dec.quantize(_TWO_PLACES, rounding=ROUND_HALF_UP)


def _parse_issued_at(value: Any) -> datetime:
    if isinstance(value, datetime):
        dt = value
    elif isinstance(value, str):
        try:
            dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
        except ValueError as exc:
            raise ValueError("issued_at must be a valid ISO 8601 datetime") from exc
    else:
        raise ValueError("issued_at must be a datetime or ISO 8601 string")

    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


class InvoiceLine(BaseModel):
    model_config = ConfigDict(extra="forbid")

    sku: str
    quantity: int = Field(ge=1)
    unit_price: Decimal

    @field_validator("unit_price", mode="before")
    @classmethod
    def _validate_unit_price(cls, value: Any) -> Decimal:
        return _to_decimal_2dp(value)

    @field_serializer("unit_price")
    def _serialize_unit_price(self, value: Decimal) -> str:
        return f"{value.quantize(_TWO_PLACES):.2f}"


class InvoicePayload(BaseModel):
    model_config = ConfigDict(extra="forbid")

    number: str
    issued_at: datetime
    lines: list[InvoiceLine]
    total: Optional[Decimal] = None

    @field_validator("issued_at", mode="before")
    @classmethod
    def _validate_issued_at(cls, value: Any) -> datetime:
        return _parse_issued_at(value)

    @model_validator(mode="after")
    def _compute_total(self) -> "InvoicePayload":
        total = Decimal("0.00")
        for line in self.lines:
            total += Decimal(line.quantity) * line.unit_price
        self.total = total.quantize(_TWO_PLACES)
        return self

    @field_serializer("issued_at")
    def _serialize_issued_at(self, value: datetime) -> str:
        value = value.astimezone(timezone.utc).replace(microsecond=0)
        return value.isoformat().replace("+00:00", "Z")

    @field_serializer("total")
    def _serialize_total(self, value: Decimal | None) -> str | None:
        if value is None:
            return None
        return f"{value.quantize(_TWO_PLACES):.2f}"


def export_invoice(data: dict) -> str:
    """
    Validate an invoice payload and return JSON text for the billing API.

    Expected input:
      - number: str
      - issued_at: ISO 8601 string or datetime; naive datetimes are treated as UTC
      - lines: list of {"sku": str, "quantity": int >= 1, "unit_price": decimal >= 0}

    Output JSON contains:
      - number
      - issued_at formatted as YYYY-MM-DDTHH:MM:SSZ
      - lines with unit_price as a string with exactly two decimals
      - total as a string with exactly two decimals
    """
    if not isinstance(data, dict):
        raise ValueError("invoice must be a dict")

    try:
        invoice = InvoicePayload.model_validate(data)
        return invoice.model_dump_json(exclude_none=True)
    except ValidationError as exc:
        raise ValueError(str(exc)) from exc

from __future__ import annotations

from typing import Any

from pydantic import BaseModel, ConfigDict, field_validator


class Profile(BaseModel):
    model_config = ConfigDict(populate_by_name=True)

    user_id: int
    display_name: str
    zip_code: str
    bio: str | None = None
    website: str | None = None

    @classmethod
    def clean_display_name(cls, value: Any):
        if isinstance(value, str):
            cleaned = " ".join(value.split())
            if cleaned == "":
                raise ValueError("display_name cannot be blank")
            return cleaned
        return value

    @field_validator("display_name", mode="before")
    @classmethod
    def _validate_display_name(cls, value: Any):
        return cls.clean_display_name(value)

    @field_validator("zip_code", mode="before")
    @classmethod
    def _validate_zip_code(cls, value: Any):
        if isinstance(value, int):
            return str(value)
        return value


def load_profile(data):
    """Validate a profile payload (dict) and return a Profile. Raises ValidationError if invalid."""
    return Profile.model_validate(data)


def public_view(profile):
    """Dict for the public API: everything except user_id, leaving out fields that are None."""
    return profile.model_dump(exclude={"user_id"}, exclude_none=True)


def apply_changes(profile, changes):
    """Return a copy of `profile` with the given field values replaced; the original is unchanged."""
    merged = profile.model_dump()
    merged.update(changes)
    return Profile.model_validate(merged)


def import_profiles(rows: list) -> list:
    """
    Validate profile rows and return valid ones as dicts with keys:
    user_id, display_name, bio, zip_code.

    Invalid rows are skipped silently.
    """
    results: list[dict[str, Any]] = []
    for row in rows:
        try:
            profile = Profile.model_validate(row)
        except Exception:
            continue

        results.append(
            profile.model_dump(
                include={"user_id", "display_name", "bio", "zip_code"},
                exclude_none=False,
            )
        )

    return results

from __future__ import annotations

import re
from typing import Any

from pydantic import BaseModel, ConfigDict, Field, ValidationError, field_validator, model_validator


_USERNAME_RE = re.compile(r"^[a-z0-9_]{3,20}$")
_ALLOWED_PHONE_STRIP = {" ", ".", "-", "(", ")"}


class _SignupPayload(BaseModel):
    model_config = ConfigDict(extra="ignore")

    username: str
    email: str
    phone: str
    password: str = Field(min_length=8)
    password_confirm: str = Field(min_length=8)

    @field_validator("username")
    @classmethod
    def _validate_username(cls, value: Any) -> str:
        if not isinstance(value, str) or not _USERNAME_RE.fullmatch(value):
            raise ValueError("invalid username")
        return value

    @field_validator("email")
    @classmethod
    def _validate_email(cls, value: Any) -> str:
        if not isinstance(value, str):
            raise ValueError("email must be a string")
        cleaned = value.strip().lower()
        if "@" not in cleaned:
            raise ValueError("invalid email")
        return cleaned

    @field_validator("phone", mode="before")
    @classmethod
    def _validate_phone(cls, value: Any) -> str:
        if not isinstance(value, str):
            raise ValueError("phone must be a string")

        compact = "".join(ch for ch in value if ch not in _ALLOWED_PHONE_STRIP)

        if not compact.startswith("+"):
            raise ValueError("phone must start with '+'")
        digits = compact[1:]
        if not digits.isdigit():
            raise ValueError("phone must contain only digits after '+'")
        if not (8 <= len(digits) <= 15):
            raise ValueError("phone must contain 8 to 15 digits")
        return compact

    @model_validator(mode="after")
    def _validate_passwords_match(self) -> "_SignupPayload":
        if self.password != self.password_confirm:
            raise ValueError("passwords do not match")
        return self


def validate_signup(data: dict) -> dict:
    """
    Validate a sign-up payload and return:
        {"username": ..., "email": ..., "phone": <compact phone>}

    Raises ValueError (including pydantic.ValidationError) for missing or invalid fields.
    """
    payload = _SignupPayload.model_validate(data)
    return {
        "username": payload.username,
        "email": payload.email,
        "phone": payload.phone,
    }
